// Map over all incoming rows (WAN1, WAN2, or both)
return $input.all().map(entry => {
  const item = entry.json;
  const is100 = item.triggered_tier === '100';
  const is95 = item.triggered_tier === '95';

  let header = '⚠️ <b>تحذير: استهلاك 80% من باقة الإنترنت</b>';
  let advice = 'ℹ️ <i>متبقي أكثر من نصف الشهر تقريباً، يرجى الانتباه لمعدل الاستهلاك اليومي.</i>';

  if (is100) {
    header = '🛑 <b>إنذار حاسم: نفاد باقة الإنترنت بالكامل (100%)!</b>';
    advice = '🛡️ <b>تم تفعيل العزل التلقائي لمنفذ ' + item.interface_name.toUpperCase() + ' لمنع خنق السرعة وسحب التصفح. كل الترافيك موجه الآن للخط الاحتياطي.</b>';
  } else if (is95) {
    header = '🚨 <b>إنذار حرج: استهلاك 95% من باقة الإنترنت!</b>';
    advice = '⚠️ <i>يُنصح بجدولة التجديد المبكر أو ترشيد الاستهلاك لتفادي هبوط السرعة الحرج.</i>';
  }

  const text = header + '\n\n' +
    '🌐 المزود: <b>' + item.provider_name + '</b> (<code>' + item.interface_name.toUpperCase() + '</code>)\n' +
    '🖥️ الراوتر: <code>' + item.router_id + '</code>\n' +
    '📊 النسبة المستهلكة: <b>' + item.used_percentage + '%</b>\n' +
    '📉 المتبقي الفعلي: <b>' + item.remaining_gb + ' GB</b> من أصل ' + item.quota_gb + ' GB\n' +
    '⏳ الأيام المتبقية: <b>' + item.days_left + ' يوم</b> (التجديد: ' + item.renewal_date + ')\n\n' +
    advice;

  return {
    json: {
      ...item,
      alert_message: text
    }
  };
});
